      width: 86px;
    }

    /* ── Docked control panel ────────────────────────────────────────────────
       #ui is a grid cell with its own scroll, an opaque background, and roomier
       type. Generated code cannot switch it to an overlay or bottom strip.      */
    body[data-ui-layout="right"] {
      grid-template-columns: 1fr var(--ui-size, 320px);
      grid-template-rows: 1fr;
      grid-template-areas: "stage ui";
    }

    body[data-ui-layout="bottom"] {
      grid-template-columns: 1fr;
      grid-template-rows: 1fr var(--ui-size, 240px);
      grid-template-areas: "stage" "ui";
    }

    body[data-ui-layout="right"] #ui,
    body[data-ui-layout="bottom"] #ui {
      position: relative;
      grid-area: ui;
      left: auto;
      bottom: auto;
      max-width: none;
      max-height: none;
      min-width: 0;
      min-height: 0;
      width: auto;
      height: auto;
      gap: 6px;
      padding: 10px 12px;
      font-size: 12px;
      background: #fbfbfc;
      opacity: 1;
      overflow: auto;
      z-index: 1;
    }

    body[data-ui-layout="right"] #ui {
      border-left: 1px solid #dcdfe3;
    }

    body[data-ui-layout="bottom"] #ui {
      border-top: 1px solid #dcdfe3;
    }

    /* Docked labels get no text-shadow halo — they sit on a flat panel, not
       over the figure. */
    body[data-ui-layout="right"] #ui label,
    body[data-ui-layout="bottom"] #ui label {
      text-shadow: none;
    }

    /* A docked panel has real width, so let wide controls use it. */
    body[data-ui-layout="right"] #ui input[type=range],
    body[data-ui-layout="bottom"] #ui input[type=range] {
      width: 100%;
    }

    body[data-ui-layout="right"] #ui textarea,
    body[data-ui-layout="bottom"] #ui textarea {
      width: 100%;
      box-sizing: border-box;
      min-height: 180px;
      resize: vertical;
      font-family: ui-monospace, Consolas, monospace;
      font-size: 11px;
      line-height: 1.45;
      tab-size: 2;
      border: 1px solid #cfd4da;
      border-radius: 4px;
      padding: 6px 8px;
    }

    body[data-ui-layout="bottom"] #ui textarea {
      min-height: 110px;
    }

    /* ── Inline equation parse errors ────────────────────────────────────── */
    .eq-err {
      color: #c00000;
      font-size: 10px;
      max-width: 180px;
      white-space: normal;
      text-shadow: 0 1px 2px #fff;
    }

    /* ── Lightweight hover tooltip for generated 3D explainers ───────────── */
    #figTooltip {
      position: fixed;
      left: 0;
      top: 0;
      display: none;
      max-width: 210px;
      padding: 4px 8px;
      border-radius: 4px;
      background: rgba(0, 0, 0, 0.58);
      color: #fff;
      font: 11px/1.35 sans-serif;
      pointer-events: none;
      white-space: normal;
      z-index: 20;
    }
  </style>
</head>

<body data-ui-layout="right">
  <div id="stage">
    <canvas id="c"></canvas>
  </div>
  <div id="figTooltip"></div>
  <div id="ui">
    <button id="btnReset" style="display:none">Reset View</button>
    <button id="btnProjToggle" style="display:none">3D view</button>
    <!-- @FIGURE_UI_BEGIN -->
    <!-- @FIGURE_UI_END -->
  </div>

  <script src="https://cdn.jsdelivr.net/npm/expr-eval@2/dist/bundle.min.js"></script>

  <script type="importmap">
  {
    "imports": {
      "three": "https://cdn.jsdelivr.net/npm/three@0.171.0/build/three.module.js",
      "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.171.0/examples/jsm/"
    }
  }
  </script>

  <!-- Error overlay: shown if CDN fails or JS throws before rendering -->
  <div id="err-overlay" style="display:none;position:fixed;inset:0;background:#fff;z-index:999;
       display:flex;flex-direction:column;align-items:center;justify-content:center;
       font-family:sans-serif;font-size:13px;color:#555;gap:10px;">
    <span id="err-msg">⚠ Figure failed to load</span>
    <button onclick="location.reload()" style="padding:5px 14px;border:1px solid #aaa;
        border-radius:5px;background:#f5f5f5;cursor:pointer;font-size:12px;">↻ Reload</button>
  </div>

  <script>
    // Show error overlay if module scripts fail or take too long
    let _rendered = false;
    const _errOverlay = document.getElementById('err-overlay');
    window.__markRendered = () => { _rendered = true; _errOverlay.style.display = 'none'; };
    window.addEventListener('error', (e) => {
      if (!_rendered) {
        document.getElementById('err-msg').textContent = '⚠ ' + (e.message || 'Figure failed to load');
        _errOverlay.style.display = 'flex';
      }
    });
    // Timeout fallback: if nothing renders in 12s, show overlay
    setTimeout(() => {
      if (!_rendered) { _errOverlay.style.display = 'flex'; }
    }, 12000);
  </script>

  <script type="module">
    import * as THREE from 'three';
    import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

    /* ── Renderer ────────────────────────────────────────────────────────── */
    const canvas = document.getElementById('c');
    const _stage = document.getElementById('stage');
    const _ui = document.getElementById('ui');
    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });

    /* ── UI layout: keep controls in a right-side column ────────────────────
     * setUiLayout(...) is retained only so older generated payloads do not
     * crash. It deliberately cannot change the side, overlay state, or size.
     */
    function setUiLayout() {
      _autoUiLayout();
    }

    function _applyUiLayout(mode, sizePx) {
      const next = 'right';
      document.body.setAttribute('data-ui-layout', next);
      if (sizePx) document.body.style.setProperty('--ui-size', `${sizePx}px`);
    }

    // Generated figures do not get to decide panel placement: a stable right
    // column prevents controls from covering the figure and avoids layout jumps.
    function _autoUiLayout() {
      const hasEditor = Boolean(_ui.querySelector('textarea'));
      const mode = 'right';
      const start = hasEditor ? 400 : 300;
      _applyUiLayout(mode, start);
      _growDockToFit(mode, start);
    }

    // A fixed dock size still clips a long control stack in a small inline
    // figure. Grow the dock until the panel stops scrolling, capped so the
    // figure always keeps the larger share of the frame.
    function _growDockToFit(mode, startPx) {
      const cap = Math.round(window.innerWidth * 0.45);
      // Clamp down too: on a small figure the default dock can itself exceed the
      // cap, and the figure must always keep the larger share.
      let size = Math.min(startPx, cap);
      if (size !== startPx) document.body.style.setProperty('--ui-size', `${size}px`);
      let guard = 0;
      const step = () => {
        if (guard++ > 6) return;
        if (_ui.scrollHeight <= _ui.clientHeight + 2 || size >= cap) return;
        size = Math.min(cap, size + 60);
        document.body.style.setProperty('--ui-size', `${size}px`);
        requestAnimationFrame(step);
      };
      requestAnimationFrame(step);
    }

    // Re-evaluate when the generated code adds controls after first paint.
    new MutationObserver(() => {
      clearTimeout(_autoUiLayout._t);
      _autoUiLayout._t = setTimeout(_autoUiLayout, 0);
    }).observe(_ui, { childList: true, subtree: true });
    window.addEventListener('resize', () => { _autoUiLayout(); });

    /* ── Scene ───────────────────────────────────────────────────────────── */
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xffffff);

    /* ── Orthographic camera ─────────────────────────────────────────────── */
    const d = 3;                              // half-height in world units
    let aspect = canvas.clientWidth / canvas.clientHeight;
    let camera = new THREE.OrthographicCamera(
      -d * aspect, d * aspect, d, -d, 0.1, 100
    );
    camera.position.set(4, 4, 4);
    camera.lookAt(0, 0, 0);
    camera.updateProjectionMatrix();

    /* ── Controls ────────────────────────────────────────────────────────── */
    let controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;

    // Has the student orbited / panned / zoomed? OrbitControls fires 'start' on
    // pointer-down and on wheel — i.e. only on real user input — while the
    // 'change' event also fires from our own controls.update() in animate(),
    // so 'start' is the signal that does not produce false positives.
    // Consumed by the ResizeObserver: a camera the student has moved must NOT
    // be repositioned by a resize (chapter-preview iframes resize routinely).
    let _userMovedCamera = false;
    function _trackCameraInteraction(ctrl) {
      ctrl.addEventListener('start', () => { _userMovedCamera = true; });
    }
    _trackCameraInteraction(controls);

    // HOME view will be computed from the scene bounds so different scenes
    // (especially tall ones) get a consistent starting zoom/angle while
    // still allowing interactive OrbitControls.
    const HOME_POS = new THREE.Vector3();
    const HOME_TARGET = new THREE.Vector3(0, 0, 0);
    let HOME_ZOOM = 0.75;
    let _labelZoomRef = 1;      // zoom at which label scale is exactly 1
    let _lastViewArgs = null;   // last resolved setCameraView args, re-applied on resize

    document.getElementById('btnReset').addEventListener('click', () => {
      if (_lastViewArgs) { setCameraView(_lastViewArgs); return; }
      camera.position.copy(HOME_POS);
      controls.target.copy(HOME_TARGET);
      camera.zoom = HOME_ZOOM;
      camera.updateProjectionMatrix();
      controls.update();
    });

    // Framing parameters
    const FRAME_HALF_HEIGHT = d; // base frustum half-height used when computing zoom
    const FRAME_MARGIN = 0.08;   // fraction of extra space around content
    const MIN_ZOOM = 0.2;
    const MAX_ZOOM = 5;

    function computeSceneBounds() {
      const box = new THREE.Box3().setFromObject(scene);
      if (box.isEmpty()) {
        // fallback box so empty scenes get a sensible frame
        box.setFromCenterAndSize(new THREE.Vector3(0, 0, 0), new THREE.Vector3(2 * d, 2 * d, 2 * d));
      }
      const center = new THREE.Vector3();
      box.getCenter(center);
      const size = new THREE.Vector3();
      box.getSize(size);
      return { box, center, size };
    }

    /**
     * setCameraView(options)
     * - azimuthDeg: horizontal angle around Y axis, in degrees.
     * - elevationDeg: angle above the ground/XZ plane, in degrees.
     * - zoom: optional orthographic zoom. If omitted, derived from content bounds.
     * - target: optional [x,y,z] camera target. If omitted, uses scene bounds center.
     * - heightFraction: fraction of the view the content's height should occupy.
     * This is the preferred per-figure camera API for matching the source image.
     */
    /* ── Oblique projection ──────────────────────────────────────────────── */
    // An oblique projection is a shear of EYE-SPACE coordinates, applied before
    // the orthographic projection: P' = P_ortho · S. It is deliberately NOT a
    // shear of the geometry — keeping it in the camera means addLabel/_syncLabels
    // (which call pos.project(camera)) track it with no extra work.
    //
    // Known limitation: Raycaster.setFromCamera derives its ray direction from
    // the camera's view axis, not the sheared projection direction, so
    // registerInteractive hit-testing is approximate at large depth under
    // oblique. Acceptable for the shallow diagrams oblique is used for.
    let _obliqueState = null;        // { angleDeg, depthScale, shearAmt, shearTarget } or null

    function _applyObliqueShear() {
      if (!_obliqueState || !camera.isOrthographicCamera) return;
      const th = THREE.MathUtils.degToRad(_obliqueState.angleDeg);
      // shearAmt eases 1 -> 0 to reveal the true 3D shape. Both the shear terms
      // and the zt pinning terms below carry the same k, so the target plane
      // stays pinned and the figure does not drift while un-shearing.
      const k = _obliqueState.depthScale * _obliqueState.shearAmt;
      // Shear about the PROJECTION PLANE (the controls target's eye-space
      // depth zt), not about the camera origin. The camera looks down -Z with
      // the target at distance ~R, so every scene point has eye z ~= -R, not
      // ~= 0. Shearing raw z would add a large rigid translation
      // (cos(th)*k*R, sin(th)*k*R) to the ENTIRE scene, shoving it off-screen.
      // Shearing (z - zt) instead pins the target plane in place and only
      // tilts depth around it -- the textbook definition of an oblique
      // projection about the picture plane.
      camera.updateMatrixWorld();
      const zt = controls.target.clone().applyMatrix4(camera.matrixWorldInverse).z;
      const S = new THREE.Matrix4().set(
        1, 0, -Math.cos(th) * k, Math.cos(th) * k * zt,
        0, 1, -Math.sin(th) * k, Math.sin(th) * k * zt,
        0, 0, 1, 0,
        0, 0, 0, 1
      );
      // Post-multiply: S acts on eye space, then P_ortho projects.
      camera.projectionMatrix.multiply(S);
      camera.projectionMatrixInverse.copy(camera.projectionMatrix).invert();
    }

    // Re-apply the shear after ANY updateProjectionMatrix() — OrbitControls calls
    // it on every zoom, which would otherwise silently wipe the shear.
    function _installObliqueHook(cam) {
      if (cam.__obliqueHooked) return;
      const base = cam.updateProjectionMatrix.bind(cam);
      cam.updateProjectionMatrix = function () {
        base();
        _applyObliqueShear();
      };
      cam.__obliqueHooked = true;
    }

    function _setObliqueEnabled(on) {
      const btn = document.getElementById('btnProjToggle');
      if (on) {
        _obliqueState = _obliqueState || { angleDeg: 45, depthScale: 0.5, shearAmt: 1, shearTarget: 1 };
        _obliqueState.shearTarget = 1;
        if (btn) { btn.style.display = ''; btn.textContent = '3D view'; }
        // Oblique is only meaningful from its authored front-on pose. Setting
        // shearTarget BEFORE this call matters: setCameraView preserves the
        // current shearTarget rather than forcing it to 1, so the 1 set above is
        // what survives and drives the ease back to the printed view.
        if (_lastViewArgs) { setCameraView(_lastViewArgs); return; }
      } else if (_obliqueState) {
        // Keep the state object alive so animate() can ease shearAmt down to 0.
        // It is cleared only when setCameraView leaves the oblique projection.
        _obliqueState.shearTarget = 0;
        if (btn) btn.textContent = 'Figure view';
      }
      camera.updateProjectionMatrix();
      controls.update();
    }

    document.getElementById('btnProjToggle').addEventListener('click', () => {
      if (!_obliqueState) return;
      if (_obliqueState.shearTarget > 0.5) {
        _setObliqueEnabled(false);
      } else {
        _setObliqueEnabled(true);
      }
    });

    // Drag to reveal: past a small threshold, ease the shear out so the student
    // sees the true 3D object they are turning. The threshold separates a drag
    // from a click, so clicking an interactive element does not collapse the
    // figure.
    const _REVEAL_DRAG_PX = 6;
    let _revealPointerDown = false;
    let _revealDragPx = 0;
    let _revealLastX = 0;
    let _revealLastY = 0;

    canvas.addEventListener('pointerdown', (e) => {
      _revealPointerDown = true;
      _revealDragPx = 0;
      _revealLastX = e.clientX;
      _revealLastY = e.clientY;
    });
    window.addEventListener('pointerup', () => { _revealPointerDown = false; });
    canvas.addEventListener('pointermove', (e) => {
      if (!_revealPointerDown || !_obliqueState || _obliqueState.shearTarget === 0) return;
      // movementX/Y are unavailable in some environments; fall back to a
      // clientX/Y delta against the previous move so the accumulator never
      // goes NaN and silently disables drag-to-reveal.
      const _dx = typeof e.movementX === 'number' ? e.movementX : (e.clientX - _revealLastX);
      const _dy = typeof e.movementY === 'number' ? e.movementY : (e.clientY - _revealLastY);
      _revealLastX = e.clientX;
      _revealLastY = e.clientY;
      _revealDragPx += Math.abs(_dx) + Math.abs(_dy);
      if (_revealDragPx > _REVEAL_DRAG_PX) {
        _obliqueState.shearTarget = 0;
        const btn = document.getElementById('btnProjToggle');
        if (btn) btn.textContent = 'Figure view';
      }
    });

    /**
     * _ensureCamera(kind) → boolean
     * Rebuilds `camera` and `controls` when the required camera class changes.
     * OrbitControls caches its object, so it is disposed and reconstructed
     * rather than re-pointed. Returns true when a swap happened.
     */
    function _ensureCamera(kind) {
      const want = kind === 'perspective' ? 'perspective' : 'orthographic';
      const have = camera.isPerspectiveCamera ? 'perspective' : 'orthographic';
      if (want === have) return false;

      const prevTarget = controls.target.clone();
      controls.dispose();

      camera = want === 'perspective'
        ? new THREE.PerspectiveCamera(35, aspect, 0.1, 1000)
        : new THREE.OrthographicCamera(-d * aspect, d * aspect, d, -d, 0.1, 100);

      controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      controls.dampingFactor = 0.05;
      controls.target.copy(prevTarget);
      _trackCameraInteraction(controls);   // the old listener died with the old controls

      if (window.__figverify) {
        window.__figverify.camera = camera;
        window.__figverify.controls = controls;
      }
      return true;
    }

    // Solve an orthographic camera pose from the on-screen angles of the two
    // horizontal-plane axes, as measured off the source figure.
    //
    // For a camera at azimuth a, elevation e with up = (0,1,0):
    //     right = (  sin a,           0,      -cos a          )
    //     up'   = ( -cos a * sin e,   cos e,  -sin a * sin e   )
    // Projecting X=(1,0,0) and Z=(0,0,1) onto that basis and taking the angle
    // below screen horizontal gives:
    //     tan(phiX) = sin e * cot a
    //     tan(phiZ) = sin e * tan a
    // whose product and ratio invert cleanly:
    //     sin e = sqrt(tan phiX * tan phiZ)
    //     tan a = sqrt(tan phiZ / tan phiX)
    // Sanity: phiX = phiZ = 30 gives e = 35.264, a = 45 — canonical isometric.
    const ISO_FALLBACK = { azimuthDeg: 45, elevationDeg: 35.264389682754654 };

    function _solvePoseFromAxisAngles(angles) {
      // Explicit null means the source is drawn head-on: no depth to recover.
      if (angles === null) return { azimuthDeg: 90, elevationDeg: 0 };
      if (!angles || !Number.isFinite(angles.x) || !Number.isFinite(angles.z)) {
        return { ...ISO_FALLBACK };
      }
      // An axis at or past horizontal/vertical is drawn edge-on; the inversion
      // has no finite solution there.
      if (angles.x <= 0 || angles.x >= 90 || angles.z <= 0 || angles.z >= 90) {
        return { ...ISO_FALLBACK };
      }
      const tX = Math.tan(THREE.MathUtils.degToRad(angles.x));
      const tZ = Math.tan(THREE.MathUtils.degToRad(angles.z));
      const sinSq = tX * tZ;
      // sin^2(e) >= 1 admits no real elevation.
      if (!(sinSq > 0) || sinSq >= 1) return { ...ISO_FALLBACK };
      return {
        azimuthDeg: THREE.MathUtils.radToDeg(Math.atan(Math.sqrt(tZ / tX))),
        elevationDeg: THREE.MathUtils.radToDeg(Math.asin(Math.sqrt(sinSq))),
      };
    }

    function setCameraView({
      projection = 'orthographic',
      azimuthDeg: azimuthDegArg = 45,
      elevationDeg: elevationDegArg = 35,
      rollDeg = 0,
      obliqueAngleDeg = 45,
      depthScale = 0.5,
      zoom = null,
      target = null,
      heightFraction = 0.5,
      distanceScale = 1.2,
      axisScreenAngles = undefined
    } = {}) {
      let azimuthDeg = azimuthDegArg;
      let elevationDeg = elevationDegArg;
      // Measured axis angles win over any guessed azimuth/elevation. Oblique
      // overrides both below — its pose is fixed front-on by definition.
      if (axisScreenAngles !== undefined) {
        const solved = _solvePoseFromAxisAngles(axisScreenAngles);
        azimuthDeg = solved.azimuthDeg;
        elevationDeg = solved.elevationDeg;
      }
      const mode = projection === 'perspective' ? 'perspective'
        : projection === 'oblique' ? 'oblique'
          : 'orthographic';
      _ensureCamera(mode === 'perspective' ? 'perspective' : 'orthographic');
      _installObliqueHook(camera);
      if (mode === 'oblique') {
        // Preserve BOTH the in-flight shearAmt and the current shearTarget.
        // The ResizeObserver re-applies _lastViewArgs on every resize, and a
        // button click does not set _userMovedCamera — so hardcoding
        // shearTarget: 1 here would silently re-shear a figure the student had
        // already revealed. Task 3's "Figure view" button still works because it
        // sets shearTarget = 1 *before* calling setCameraView, and that value is
        // what gets preserved here.
        const _prevShearAmt = _obliqueState ? _obliqueState.shearAmt : 1;
        const _prevShearTarget = _obliqueState ? _obliqueState.shearTarget : 1;
        _obliqueState = {
          angleDeg: Number.isFinite(obliqueAngleDeg) ? obliqueAngleDeg : 45,
          depthScale: Number.isFinite(depthScale) ? depthScale : 0.5,
          shearAmt: _prevShearAmt,
          shearTarget: _prevShearTarget,
        };
        // Rotation stays enabled: dragging is how the student reveals the true
        // shape. The drag listener eases the shear out as they turn the figure.
        controls.enableRotate = true;
        const btn = document.getElementById('btnProjToggle');
        // Label reflects the PRESERVED shearTarget, not an assumed "just enabled"
        // state -- otherwise a resize while revealed (shearTarget 0) would flip
        // the label back to '3D view' even though the shear itself stayed put.
        if (btn) { btn.style.display = ''; btn.textContent = _prevShearTarget > 0.5 ? '3D view' : 'Figure view'; }
      } else {
        _obliqueState = null;
        controls.enableRotate = true;
        const btn = document.getElementById('btnProjToggle');
        if (btn) btn.style.display = 'none';
      }

      const { box, center, size } = computeSceneBounds();
      const viewTarget = Array.isArray(target)
        ? new THREE.Vector3(target[0] || 0, target[1] || 0, target[2] || 0)
        : center;

      // Oblique is defined by a front-on viewpoint; depth comes from the shear.
      if (mode === 'oblique') { azimuthDeg = 90; elevationDeg = 0; }

      const radius = Math.max(size.length() * distanceScale, FRAME_HALF_HEIGHT * 2);
      const azimuth = THREE.MathUtils.degToRad(azimuthDeg);
      const elevation = THREE.MathUtils.degToRad(elevationDeg);
      const cosElev = Math.cos(elevation);
      const dir = new THREE.Vector3(
        Math.cos(azimuth) * cosElev,
        Math.sin(elevation),
        Math.sin(azimuth) * cosElev
      ).normalize();

      camera.position.copy(dir).multiplyScalar(radius).add(viewTarget);
      camera.up.set(0, 1, 0);
      if (Number.isFinite(rollDeg) && rollDeg !== 0) {
        camera.up.applyAxisAngle(dir.clone().negate(), THREE.MathUtils.degToRad(rollDeg));
      }
      camera.lookAt(viewTarget);
      camera.updateMatrixWorld();

      // Project all 8 bounding-box corners into view space. View-space X and Y
      // are independent of how far the camera sits along its own view axis, so
      // this extent is valid for both projections.
      const toView = camera.matrixWorldInverse;
      const pt = new THREE.Vector3();
      // Under oblique, camera.projectionMatrix will get a depth shear baked in
      // (about the target's eye-space depth, see _applyObliqueShear) AFTER
      // this fit runs. If the fit measured the UNsheared extent, the shear
      // would inflate the actually-drawn projection beyond what was fit,
      // breaking heightFraction (and, at large heightFraction, clipping the
      // figure off-screen). So replicate the same shear here before measuring.
      const obliqueTh = mode === 'oblique' ? THREE.MathUtils.degToRad(_obliqueState.angleDeg) : 0;
      const obliqueK = mode === 'oblique' ? _obliqueState.depthScale * _obliqueState.shearAmt : 0;
      const ztFit = mode === 'oblique' ? viewTarget.clone().applyMatrix4(toView).z : 0;
      let minVY = Infinity, maxVY = -Infinity, minVX = Infinity, maxVX = -Infinity;
      for (let xi = 0; xi < 2; xi++) for (let yi = 0; yi < 2; yi++) for (let zi = 0; zi < 2; zi++) {
        pt.set(xi ? box.max.x : box.min.x,
          yi ? box.max.y : box.min.y,
          zi ? box.max.z : box.min.z).applyMatrix4(toView);
        let vx = pt.x, vy = pt.y;
        if (mode === 'oblique') {
          const dz = pt.z - ztFit;
          vx -= Math.cos(obliqueTh) * obliqueK * dz;
          vy -= Math.sin(obliqueTh) * obliqueK * dz;
        }
        minVY = Math.min(minVY, vy); maxVY = Math.max(maxVY, vy);
        minVX = Math.min(minVX, vx); maxVX = Math.max(maxVX, vx);
      }
      const projH = Math.max(maxVY - minVY, 1e-6);
      const projW = Math.max(maxVX - minVX, 1e-6);
      const frac = Math.min(Math.max(heightFraction, 0.05), 1);

      if (camera.isPerspectiveCamera) {
        // Frame by DISTANCE and fov. Assigning an orthographic-derived number to
        // camera.zoom (the old behaviour) is dimensionally meaningless here.
        camera.zoom = 1;
        camera.aspect = aspect;
        const vFov = THREE.MathUtils.degToRad(camera.fov);
        const hFov = 2 * Math.atan(Math.tan(vFov / 2) * aspect);
        const distH = (projH / 2) / Math.tan(vFov / 2) / frac;
        const distW = (projW / 2) / Math.tan(hFov / 2) / frac;
        const dist = Math.max(distH, distW, 0.01);
        camera.position.copy(dir).multiplyScalar(dist).add(viewTarget);
        camera.lookAt(viewTarget);
        camera.near = Math.max(0.01, dist - radius * 2);
        camera.far = dist + radius * 4;
      } else {
        camera.near = 0.01;
        camera.far = radius * 4 + 100;
        let resolvedZoom;
        if (Number.isFinite(zoom)) {
          resolvedZoom = zoom;
        } else {
          const zH = (2 * FRAME_HALF_HEIGHT * frac) / projH;
          const zW = (2 * FRAME_HALF_HEIGHT * aspect * frac) / projW;
          resolvedZoom = Math.min(Math.max(Math.min(zH, zW), MIN_ZOOM), MAX_ZOOM);
        }
        camera.zoom = resolvedZoom;
      }

      controls.target.copy(viewTarget);
      camera.updateProjectionMatrix();
      controls.update();

      HOME_POS.copy(camera.position);
      HOME_TARGET.copy(controls.target);
      HOME_ZOOM = camera.zoom;

      _labelZoomRef = camera.zoom || 1;
      // An explicit setCameraView (including the Reset View button) is the
      // author/student asking for this exact pose, so any earlier manual
      // orbiting is superseded — resize may re-fit freely again.
      _userMovedCamera = false;
      _lastViewArgs = {
        projection: mode, azimuthDeg, elevationDeg, rollDeg,
        obliqueAngleDeg, depthScale, zoom, target, heightFraction, distanceScale,
        axisScreenAngles,
      };

      window.__figureCameraView = {
        projection: mode,
        azimuthDeg, elevationDeg, rollDeg,
        zoom: camera.zoom,
        target: [controls.target.x, controls.target.y, controls.target.z],
