    g.userData.core.material.color.setHex(on ? col : 0x9a9a9a);
  }
  mark(dotP1, p1, in1, 0xff0000); mark(dotP2, p2, in2, 0xff0000);
  mark(dotE1, e1, ine1, 0x000000); mark(dotE2, e2, ine2, 0x000000);

  // in-plane image axes
  if (S.showAxes) {
    const gA = 0x00c000, bA = 0x2a7fff;
    const o1 = f1.pt(-0.35, -1.25), o1b = f1.pt(-0.1, -0.35);
    dyn.add(new THREE.ArrowHelper(f1.v.clone(), o1, 2.25, gA, 0.26, 0.17));
    dyn.add(new THREE.ArrowHelper(f1.u.clone(), o1b, 1.55, gA, 0.26, 0.17));
    const o2 = f2.pt(0.35, -1.25), o2b = f2.pt(0.1, -0.30);
    dyn.add(new THREE.ArrowHelper(f2.v.clone(), o2, 2.25, bA, 0.26, 0.17));
    dyn.add(new THREE.ArrowHelper(f2.u.clone(), o2b, 1.45, bA, 0.26, 0.17));
    if (e1) {
      const l = f1.local(e1);
      const g = tube(f1.pt(l.a - 1.3, l.b + 0.95), f1.pt(l.a + 0.6, l.b - 0.45),
        0.012, 0x00c000, { opacity: 0.6, renderOrder: 5 });
      if (g) dyn.add(g);
    }
    if (e2) {
      const l = f2.local(e2);
      const g = tube(f2.pt(l.a + 1.3, l.b + 0.95), f2.pt(l.a - 0.6, l.b - 0.45),
        0.012, 0x2a7fff, { opacity: 0.65, renderOrder: 5 });
      if (g) dyn.add(g);
    }
  }

  /* labels */
  labP.pos.copy(P);
  labO1.pos.copy(O1); labO2.pos.copy(O2);
  labC1.pos.copy(O1); labC2.pos.copy(O2);
  labEP.pos.copy(O1).add(P).add(O2).multiplyScalar(1 / 3).add(new THREE.Vector3(0, 0.15, 0));
  labEP.div.style.display = S.showPlane ? '' : 'none';
  const show = (lab, ok, pos, dim) => {
    lab.div.style.visibility = ok ? 'visible' : 'hidden';
    if (pos) lab.pos.copy(pos);
    lab.div.style.opacity = dim ? '0.45' : '1';
  };
  show(labP1, !!p1, p1, !in1); show(labP2, !!p2, p2, !in2);
  show(labE1, !!e1, e1, !ine1); show(labE2, !!e2, e2, !ine2);
  if (seg1) labEL1.pos.copy(seg1.lo.clone().lerp(seg1.hi, 0.86));
  if (seg2) labEL2.pos.copy(seg2.lo.clone().lerp(seg2.hi, 0.86));
  labEL1.div.style.visibility = seg1 ? 'visible' : 'hidden';
  labEL2.div.style.visibility = seg2 ? 'visible' : 'hidden';

  const vP = document.getElementById('vP');
  if (vP) vP.textContent = `P = (${P.x.toFixed(1)}, ${P.y.toFixed(1)}, ${P.z.toFixed(1)})`;
  const vS = document.getElementById('vSensor');
  if (vS) {
    if (in1 && in2) { vS.style.color = '#137013'; vS.textContent = 'p₁ and p₂ both lie on their sensors.'; }
    else {
      vS.style.color = '#b35c00';
      vS.textContent = (!in1 && !in2) ? 'P projects outside both sensors (grey dots).'
        : (!in1 ? 'p₁ falls outside sensor 1 (grey dot).' : 'p₂ falls outside sensor 2 (grey dot).');
    }
  }
}

rebuild();

/* ── camera framing ──────────────────────────────────────────────────────── */
const RIG_VIEW = {
  projection: 'perspective', azimuthDeg: 84, elevationDeg: 12, rollDeg: 0,
  heightFraction: 0.78, target: [0, 0.45, -1.0]
};
setCameraView(RIG_VIEW);

function applyView() {
  if (S.viewMode === 'Camera 2 image' && f2) {
    const dc = f2.d.clone().negate();
    setCameraView({
      projection: 'perspective',
      azimuthDeg: THREE.MathUtils.radToDeg(Math.atan2(dc.z, dc.x)),
      elevationDeg: 3, rollDeg: 0,
      target: [f2.C.x, f2.C.y, f2.C.z],
      heightFraction: 0.82, distanceScale: 1.0
    });
  } else {
    setCameraView(RIG_VIEW);
  }
}

/* ── rotate the "Epipolar line" labels along their lines, every frame ────── */
const _pv = new THREE.Vector3();
function scr(p) { _pv.copy(p).project(camera); return { x: (_pv.x * 0.5 + 0.5) * canvas.clientWidth, y: (-_pv.y * 0.5 + 0.5) * canvas.clientHeight }; }
function rotLabel(lab, seg) {
  if (!seg) return;
  const A = scr(seg.lo), B = scr(seg.hi);
  let ang = Math.atan2(B.y - A.y, B.x - A.x) * 180 / Math.PI;
  if (ang > 90) ang -= 180; else if (ang < -90) ang += 180;
  const sp = lab.div.firstElementChild;
  if (sp) sp.style.transform = `rotate(${ang.toFixed(1)}deg)`;
}

/* ── interactive explanations ────────────────────────────────────────────── */
registerInteractive(pickP, {
  title: 'Scene point P',
  tooltip: 'Drag P (Shift = depth)',
  body: 'P is the 3-D world point. With the two camera centres O₁ and O₂ it spans the epipolar plane. Drag it: the plane swings about the fixed baseline, p₁ and p₂ move, but each stays on its epipolar line through the epipole.'
});
registerInteractive(triYellow, {
  title: 'Epipolar plane',
  tooltip: 'Plane through O₁, P, O₂',
  body: 'The epipolar plane contains the baseline O₁O₂ and the point P; its normal is n = (P−O₁)×(P−O₂). Every epipolar plane contains the baseline, so they form a pencil of planes hinged on O₁O₂.'
});
registerInteractive(planeFill1, {
  title: 'Image plane 1',
  tooltip: 'Sensor of camera 1',
  body: 'The finite sensor of camera 1 at focal distance f in front of O₁. The epipolar plane cuts it in a straight line — the epipolar line — which passes through the epipole e₁ and through p₁, the image of P.'
});
registerInteractive(planeFill2, {
  title: 'Image plane 2',
  tooltip: 'Sensor of camera 2',
  body: 'Given p₁ in image 1, the matching point p₂ must lie on the epipolar line in image 2. That turns stereo correspondence from a 2-D search over the whole image into a 1-D search along one line. Note the epipole can fall outside the finite sensor.'
});

/* ── dragging P ──────────────────────────────────────────────────────────── */
const _ray = new THREE.Raycaster();
const _nd = new THREE.Vector2();
const _dragPlane = new THREE.Plane();
const _hitPt = new THREE.Vector3();
let dragging = false; const dragOff = new THREE.Vector3();

function setNdc(ev) {
  const r = canvas.getBoundingClientRect();
  _nd.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  _nd.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
}
canvas.addEventListener('pointerdown', (ev) => {
  setNdc(ev);
  _ray.setFromCamera(_nd, camera);
  if (_ray.intersectObject(pickP, false).length) {
    dragging = true; controls.enabled = false;
    const n = ev.shiftKey ? new THREE.Vector3(0, 1, 0)
      : camera.getWorldDirection(new THREE.Vector3()).negate();
    _dragPlane.setFromNormalAndCoplanarPoint(n, S.P);
    if (_ray.ray.intersectPlane(_dragPlane, _hitPt)) dragOff.copy(S.P).sub(_hitPt);
    else dragOff.set(0, 0, 0);
    canvas.setPointerCapture?.(ev.pointerId);
  }
});
canvas.addEventListener('pointermove', (ev) => {
  if (!dragging) return;
  setNdc(ev);
  _ray.setFromCamera(_nd, camera);
  const n = ev.shiftKey ? new THREE.Vector3(0, 1, 0)
    : camera.getWorldDirection(new THREE.Vector3()).negate();
  _dragPlane.setFromNormalAndCoplanarPoint(n, S.P);
  if (_ray.ray.intersectPlane(_dragPlane, _hitPt)) {
    const np = _hitPt.clone().add(dragOff);
    S.P.set(
      THREE.MathUtils.clamp(np.x, P_DOM.x[0], P_DOM.x[1]),
      THREE.MathUtils.clamp(np.y, P_DOM.y[0], P_DOM.y[1]),
      THREE.MathUtils.clamp(np.z, P_DOM.z[0], P_DOM.z[1])
    );
    rebuild();
  }
});
function endDrag() { if (dragging) { dragging = false; controls.enabled = true; } }
window.addEventListener('pointerup', endDrag);
window.addEventListener('pointercancel', endDrag);

/* ── UI wiring ───────────────────────────────────────────────────────────── */
const sBase = document.getElementById('sBase'), vBase = document.getElementById('vBase');
const sYaw = document.getElementById('sYaw'), vYaw = document.getElementById('vYaw');
const btnRig = document.getElementById('btnRig'), btnImg = document.getElementById('btnImg');
const cbPlane = document.getElementById('cbPlane'), cbAxes = document.getElementById('cbAxes');

sBase.addEventListener('input', () => {
  S.baseline = parseFloat(sBase.value);
  vBase.textContent = S.baseline.toFixed(1);
  rebuild();
  if (S.viewMode === 'Camera 2 image') applyView();
});
sYaw.addEventListener('input', () => {
  S.cam2Yaw = parseFloat(sYaw.value);
  vYaw.textContent = S.cam2Yaw.toFixed(0);
  rebuild();
  if (S.viewMode === 'Camera 2 image') applyView();
});
cbPlane.addEventListener('change', () => { S.showPlane = cbPlane.checked; rebuild(); });
cbAxes.addEventListener('change', () => { S.showAxes = cbAxes.checked; rebuild(); });

function setViewMode(m) {
  S.viewMode = m;
  btnRig.classList.toggle('active', m === '3D rig');
  btnImg.classList.toggle('active', m === 'Camera 2 image');
  rebuild(); applyView();
}
btnRig.addEventListener('click', () => setViewMode('3D rig'));
btnImg.addEventListener('click', () => setViewMode('Camera 2 image'));
document.getElementById('btnResetP').addEventListener('click', () => {
  S.P.copy(P_DEFAULT); rebuild();
});

/* ── demo steps ──────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: '1. The two-view rig',
    text: 'Two camera centres O₁ and O₂ with their image planes face inward; the dashed baseline joins them and pierces each sensor at the epipoles e₁ and e₂.',
    state: { baseline: 8, cam2Yaw: -20, viewMode: '3D rig' }
  },
  {
    title: '2. One point, one plane',
    text: 'The scene point P plus the two centres span the yellow epipolar plane; the red rays O₁P and O₂P lie in it and pierce the sensors at p₁ and p₂.',
    state: { baseline: 8, cam2Yaw: -20, viewMode: '3D rig' }
  },
  {
    title: '3. Epipolar lines are intersections',
    text: 'Where the yellow plane cuts each image plane you get the epipolar line — it necessarily runs through the epipole and through the projected point.',
    state: { baseline: 8, cam2Yaw: -20, viewMode: '3D rig' }
  },
  {
    title: '4. Change the relative pose',
    text: 'A shorter baseline moves p₁ and p₂ (disparity shrinks); rotating camera 2 slides e₂ and swings its epipolar line. The constraint is fixed by the relative pose (R, t) alone — never by the scene.',
    state: { baseline: 4.5, cam2Yaw: 30, viewMode: '3D rig' }
  },
  {
    title: '5. 2-D search becomes 1-D',
    text: 'Looking straight into camera 2’s image, the match for p₁ can only lie along the single epipolar line through e₂ (red band).',
    state: { baseline: 8, cam2Yaw: -20, viewMode: 'Camera 2 image' }
  }
];
let stepIdx = 0, tween = null, playing = false;
const elTitle = document.getElementById('stepTitle'), elText = document.getElementById('stepText');
const elInd = document.getElementById('stepInd');

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  elTitle.textContent = st.title;
  elText.textContent = st.text;
  elInd.textContent = `${stepIdx + 1} / ${STEPS.length}`;
  tween = {
    from: { baseline: S.baseline, cam2Yaw: S.cam2Yaw },
    to: { baseline: st.state.baseline, cam2Yaw: st.state.cam2Yaw },
    t0: performance.now(), dur: 700
  };
  if (st.state.viewMode !== S.viewMode) setViewMode(st.state.viewMode);
}
function tick() {
  requestAnimationFrame(tick);
  if (tween) {
    const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    S.baseline = tween.from.baseline + (tween.to.baseline - tween.from.baseline) * e;
    S.cam2Yaw = tween.from.cam2Yaw + (tween.to.cam2Yaw - tween.from.cam2Yaw) * e;
    sBase.value = S.baseline; vBase.textContent = S.baseline.toFixed(1);
    sYaw.value = S.cam2Yaw; vYaw.textContent = S.cam2Yaw.toFixed(0);
    rebuild();
    if (S.viewMode === 'Camera 2 image') applyView();
    if (k >= 1) {
      tween = null;
      if (playing) setTimeout(() => {
        if (!playing) return;
        if (stepIdx === STEPS.length - 1) {
          playing = false; document.getElementById('btnPlay').textContent = 'Play'; return;
        }
        goToStep(stepIdx + 1);
      }, 1500);
    }
  }
  rotLabel(labEL1, seg1);
  rotLabel(labEL2, seg2);
}
tick();
document.getElementById('btnPrev').addEventListener('click', () => {
  playing = false; document.getElementById('btnPlay').textContent = 'Play'; goToStep(stepIdx - 1);
});
document.getElementById('btnNext').addEventListener('click', () => {
  playing = false; document.getElementById('btnPlay').textContent = 'Play'; goToStep(stepIdx + 1);
});
document.getElementById('btnPlay').addEventListener('click', (e) => {
  playing = !playing;
  e.target.textContent = playing ? 'Pause' : 'Play';
  if (playing) goToStep(stepIdx === STEPS.length - 1 ? 0 : stepIdx);
});
goToStep(0);
// @FIGURE_CODE_END
